appearances.css:
.app{display:flex!important;flex-wrap:wrap;align-items:center;gap:3px 4px;padding:4px;font-size:9px;border-radius:5px}
.app>*{min-width:0}
.row{display:contents}
select,button,input[type=file]{font-size:9px;padding:2px 4px;border-radius:3px}
button{height:24px;padding:0 6px;white-space:nowrap}
.row>select{order:1;flex:0 1 170px;height:24px}
.row>label{order:2;display:flex;align-items:center;gap:2px;font-size:9px;white-space:nowrap;padding:3px 2px}
.row>label input{margin:0 2px 0 0}
.row>button{order:3}
.app>.line{order:5;display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0;width:92px;flex:0 0 92px}
.app>.line>span{order:2;font-size:7.5px;line-height:1.1;text-align:center;letter-spacing:-.03em}
.app>.line>.kn{order:1;width:28px!important;height:28px!important}
.app>.line>.kn svg{width:100%;height:100%}
.mt{order:4;flex:1 1 100%;gap:2px}
.mr{gap:4px;min-height:10px}
.mr>span{width:44px;font-size:9px;white-space:nowrap}
pre{order:6;flex:1 1 245px;padding:3px 5px;font-size:8px;line-height:1.3;border-radius:4px;align-self:stretch}
.screen{order:7;flex:1 1 90px;height:auto;min-height:48px;align-self:stretch;border-radius:4px}
.proposal{order:8;flex:1 1 100%;padding:2px 5px;font-size:9px;line-height:1.3}
.grid{order:9;flex:1 1 100%;display:flex;flex-wrap:wrap;gap:4px}
.grp{display:flex;flex-wrap:wrap;align-content:flex-start;gap:2px 0;padding:3px;border:1px solid var(--line);background:var(--card-2);border-radius:4px;min-width:0}
.control{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0;padding:0;border:0;background:none;border-radius:0;min-width:0;flex:1 1 56px}
.control .line{display:contents}
.control .line>span{order:4;max-width:100%;font-size:7.5px;line-height:1.1;text-align:center;letter-spacing:-.03em;overflow-wrap:anywhere}
.control .line>output{order:2;font-size:8px;line-height:1.1;text-align:center;white-space:nowrap}
.control .line>input{order:1;margin:7px 0 6px}
.control>input[type=range]{order:1}
.control>.kn{order:1;width:28px!important;height:28px!important;justify-self:center}
.control>.kn svg{width:100%;height:100%}
.control>select{order:1;width:100%;height:24px;padding:2px 0;font-size:8px;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;cursor:pointer}
.control:has(>select){flex:2 1 100px}
.control:has(>select) .line>span{order:2}
.control:has(>select) .lock{order:3}
.lock{order:3;display:flex;align-items:center;justify-content:center;gap:1px;font-size:7.5px;padding:1px 0 0}
.lock input{margin:0 2px 0 0;width:11px;height:11px}
.status{order:10;flex:1 1 100%;font-size:8.5px;line-height:1.2}
.grp[data-g=sat]{flex:1 1 100%}
.grp[data-g=sat] .control{flex:1 1 100px}
